// ── Build the Apify actor call from Whizz's search request ──
// compass/crawler-google-places is the standard Google Maps scraper actor on Apify — its
// searchStringsArray/locationQuery/maxCrawledPlacesPerSearch input shape is well documented,
// unlike the 2GIS actor (see the sibling whizz-discover-2gis workflow's notes on that one).
// No API token here — Call Apify Google Maps Actor authenticates via n8n's native Apify
// credential (Authentication: Predefined Credential Type → Apify API) instead of a token in code.
const body = $('Webhook').first().json.body || {};
const brand = (body.brand || '').trim();
const category = (body.category || '').trim();
const type = (body.type || '').trim();
const location = (body.location || '').trim();
const query = (body.query || [brand, category, type].filter(Boolean).join(' ')).trim();

// A single run can crawl deep into Google Maps' result list — 100 gives real breadth on a
// broad category/city without over-running Apify usage on every click of "Discover".
const APIFY_MAPS_HARD_CAP = 100;
const limit = Math.max(1, Math.min(Number(body.limit) || 20, APIFY_MAPS_HARD_CAP));

const ACTOR_ID = 'compass~crawler-google-places';

return [{
  json: {
    actorId: ACTOR_ID,
    actorInput: {
      searchStringsArray: [query],
      locationQuery: location,
      maxCrawledPlacesPerSearch: limit,
      language: 'en',
      skipClosedPlaces: true
    }
  }
}];

// ── Normalize the Apify dataset into what Whizz's Contact Discovery UI expects ──
const items = $input.all();
let rawItems = [];
let apiError = null;

for (const item of items) {
  const j = item.json;
  if (j && j.error) { apiError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); continue; }
  if (Array.isArray(j)) rawItems.push(...j);
  else if (j) rawItems.push(j);
}

if (apiError) {
  return [{ json: { contacts: [], error: `Google Maps/Apify error: ${apiError}` } }];
}

// dedupe within a single run — the actor can repeat a place across paginated result pages
const seen = new Set();
const contacts = [];
for (const it of rawItems) {
  const name = it.title || it.name || '';
  if (!name) continue;
  // placeId/cid is a stable per-place id from Google itself — the strongest possible key so
  // Whizz can tell "already imported, refresh it" from "brand new" on repeated searches
  const sourceId = String(it.placeId || it.cid || it.fid || it.url || '').trim();
  const dedupeKey = sourceId || name.toLowerCase();
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);

  contacts.push({
    name,
    phone: it.phone || it.phoneUnformatted || (Array.isArray(it.phones) ? it.phones[0] : '') || '',
    email: it.email || (Array.isArray(it.emails) ? it.emails[0] : '') || '',
    website: it.website || it.domain || '',
    address: it.address || it.fullAddress || it.neighborhood || '',
    city: it.city || it.neighborhood || '',
    countryCode: it.countryCode || it.country || '',
    categoryName: it.categoryName || (Array.isArray(it.categories) ? it.categories[0] : '') || '',
    totalScore: it.totalScore || it.rating || 0,
    reviewsCount: it.reviewsCount || it.reviewsCount === 0 ? it.reviewsCount : (it.userRatingsTotal || 0),
    url: it.url || it.googleMapsUrl || '',
    sourceId
  });
}

return [{ json: { contacts } }];
